steps.script:
var main = tree.root.get_node("Main")
var units = GameState.state["units"]
var keep = ["U_CUSTODIAN_GUARD_A", "U_MEK_GUNZ_A", "U_WARBOSS_A"]
for uid in units:
	if not uid in keep:
		for m in units[uid].get("models", []):
			m["alive"] = false
		continue
	var f = units[uid].get("flags", {})
	f["in_engagement"] = false
	f.erase("last_shot_idx")
	units[uid]["flags"] = f
# The Warboss now leads the Mek Gunz (stand-in for the 11e Big Mek -> Mek Gunz pairing).
var ad = units["U_BOYZ_B"].get("attachment_data", {})
ad["attached_characters"] = []
units["U_BOYZ_B"]["attachment_data"] = ad
units["U_MEK_GUNZ_A"]["attachment_data"] = {"attached_characters": ["U_WARBOSS_A"]}
units["U_WARBOSS_A"]["attached_to"] = "U_MEK_GUNZ_A"
var px = 40.0
var i = 0
for m in units["U_CUSTODIAN_GUARD_A"]["models"]:
	if m.get("alive", true):
		m["position"] = {"x": (10.0 + i * 1.8) * px, "y": 10.0 * px}
		i += 1
units["U_MEK_GUNZ_A"]["models"][0]["position"] = {"x": 14.0 * px, "y": 31.0 * px}
units["U_WARBOSS_A"]["models"][0]["position"] = {"x": 16.5 * px, "y": 31.5 * px}
TerrainManager.set_meta("phl_saved_terrain", TerrainManager.terrain_features.duplicate(true))
var poly = PackedVector2Array([Vector2(15.5, 30.5) * px, Vector2(17.5, 30.5) * px, Vector2(17.5, 32.5) * px, Vector2(15.5, 32.5) * px])
TerrainManager.terrain_features = [{"id": "phl_light_area", "type": "barricade", "height_category": "low", "polygon": poly}]
TerrainManager.emit_signal("terrain_loaded", TerrainManager.terrain_features)
SettingsService.set_auto_allocate_wounds(false)
PhaseManager.get_current_phase_instance().update_local_state(GameState.create_snapshot())
main._recreate_unit_visuals()
main.get_node("ShootingController")._refresh_unit_list(false)
return "ok"

var units = GameState.state["units"]
var w = units["U_WARBOSS_A"]
var wm = w["models"][0]
var mg = units["U_MEK_GUNZ_A"]
var seen_by = 0
var nearest = INF
for cm in units["U_CUSTODIAN_GUARD_A"]["models"]:
	if not cm.get("alive", true):
		continue
	nearest = minf(nearest, Measurement.model_to_model_distance_inches(cm, wm))
	if TerrainManager.hidden_model_visible_to(wm, w, cm):
		seen_by += 1
var hid_w = TerrainManager.is_model_hidden(wm, w)
var hid_mg = TerrainManager.is_model_hidden(mg["models"][0], mg)
var tgt = RulesEngine.get_eligible_targets("U_CUSTODIAN_GUARD_A", GameState.create_snapshot(false)).has("U_MEK_GUNZ_A")
print("[%s] Warboss (INFANTRY) hidden=%s nearest Guard %.1fin, seen by %d; Mek Gunz (VEHICLE) hidden=%s; Attached unit targetable=%s" % ["precision_hidden_leader_own_keywords_11e", str(hid_w), nearest, seen_by, str(hid_mg), str(tgt)])
return "%s|%d|%s|%s" % [str(hid_w), seen_by, str(hid_mg), str(tgt)]

var sd = RulesEngine.prepare_save_resolution(4, "U_MEK_GUNZ_A", "U_CUSTODIAN_GUARD_A", {"name": "Precision Test Rifle", "ap": -3, "damage": 1, "damage_raw": "1", "keywords": [], "special_rules": "precision"}, GameState.state, {}, {}, {"has_precision": true, "precision_wounds": 4, "critical_hits": 4})
var g = RulesEngine.precision_eligible_groups_11e(sd, GameState.state)
print("[%s] PRECISION eligible groups: %s" % ["precision_hidden_leader_own_keywords_11e", str(g)])
return g.size()

var sd = RulesEngine.prepare_save_resolution(4, "U_MEK_GUNZ_A", "U_CUSTODIAN_GUARD_A", {"name": "Precision Test Rifle", "ap": -3, "damage": 1, "damage_raw": "1", "keywords": [], "special_rules": "precision"}, GameState.state, {}, {}, {"has_precision": true, "precision_wounds": 4, "critical_hits": 4})
tree.root.get_node("Main").get_node("ShootingController")._on_saves_required([sd])
return true

var units = GameState.state["units"]
var i = 0
for m in units["U_CUSTODIAN_GUARD_A"]["models"]:
	if m.get("alive", true):
		m["position"] = {"x": (10.0 + i * 1.8) * 40.0, "y": 19.0 * 40.0}
		i += 1
PhaseManager.get_current_phase_instance().update_local_state(GameState.create_snapshot())
tree.root.get_node("Main")._recreate_unit_visuals()
return "ok"

var sd = RulesEngine.prepare_save_resolution(4, "U_MEK_GUNZ_A", "U_CUSTODIAN_GUARD_A", {"name": "Precision Test Rifle", "ap": -3, "damage": 1, "damage_raw": "1", "keywords": [], "special_rules": "precision"}, GameState.state, {}, {}, {"has_precision": true, "precision_wounds": 4, "critical_hits": 4})
var g = RulesEngine.precision_eligible_groups_11e(sd, GameState.state)
print("[%s] PRECISION eligible groups: %s" % ["precision_hidden_leader_own_keywords_11e", str(g)])
return g.size()

var sd = RulesEngine.prepare_save_resolution(4, "U_MEK_GUNZ_A", "U_CUSTODIAN_GUARD_A", {"name": "Precision Test Rifle", "ap": -3, "damage": 1, "damage_raw": "1", "keywords": [], "special_rules": "precision"}, GameState.state, {}, {}, {"has_precision": true, "precision_wounds": 4, "critical_hits": 4})
tree.root.get_node("Main").get_node("ShootingController")._on_saves_required([sd])
return true

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_log_file_path(), FileAccess.READ)
if f == null:
	return -1
var n = 0
var bad = []
while not f.eof_reached():
	var l = f.get_line()
	if l.contains("[ERROR"):
		n += 1
		bad.append(l)
print("[precision_hidden_leader_own_keywords_11e log] ERROR lines = ", n, " ", bad.slice(0, 3))
return n
